    const counts = copyChipFenceCounts(text);
    let meta = copyChipFenceLineWord(counts.lines) + " · " + String(counts.chars) + " chars";
    if (String(text === undefined || text === null ? "" : text).charAt(String(text || "").length - 1) === "\n") {
      meta += " · ends with ⏎";
    }
    return meta;
